mapper.select:
select  from user_coupon c
inner join coupon_template t on c.template_id = t.id
where c.id = #{id}

mapper.update:
update user_coupon
set status = 3
where id = #{id}
  and user_id = #{userId}
  and template_id = #{templateId}
  and status = 0
  and use_order_id is null
  and expire_time > #{eligibilityTime}

mapper.select:
select  from user_coupon c
inner join coupon_template t on c.template_id = t.id
where c.user_id = #{userId}
and c.status = #{status}
order by c.obtain_time desc

select , u.name as userName, u.phone as userPhone from user_coupon c inner join coupon_template t on c.template_id = t.id left join user u on c.user_id = u.id
and c.status = #{status}
and (u.name like concat('%', #{keyword}, '%') or u.phone like concat('%', #{keyword}, '%'))
order by c.obtain_time desc limit #{page}, #{pageSize}

select count(*) from user_coupon c left join user u on c.user_id = u.id
and c.status = #{status}
and (u.name like concat('%', #{keyword}, '%') or u.phone like concat('%', #{keyword}, '%'))
